package cl.bolsillo.app;
import android.animation.ValueAnimator;import android.content.*;import android.graphics.*;import android.os.Build;import android.os.Bundle;import android.view.*;import android.view.accessibility.*;

/** Observed points only. Geometry, gradients and label fitting are cached outside animation frames. */
final class FlowChart extends View {
 final long[] values;final int color;final boolean night;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);final String[] labels;final float[] xs,ys;
 final Path line=new Path(),fill=new Path();final RectF tooltip=new RectF();final Typeface medium;
 final String[] pointDescriptions,displayLabels;final DashPathEffect guide=new DashPathEffect(new float[]{4,6},0);final long min,max;
 Shader fillMaterial,lineMaterial,tooltipMaterial;ValueAnimator animation;int selected=-1,tone;float reveal=1f,left,right,top,bottom,labelSize,tooltipSize,downX,downY;boolean dragged;String low,high;
 FlowChart(Context c,long[] values,int color){this(c,values,color,null);}
 FlowChart(Context c,long[] amounts,int color,String[] names){
  super(c);medium=Glass.font(c,500);night=Glass.dark(c);values=amounts.clone();this.color=color;labels=names==null?null:names.clone();xs=new float[values.length];ys=new float[values.length];pointDescriptions=new String[values.length];displayLabels=new String[values.length];long lo=values.length>0?values[0]:0,hi=lo;boolean hidden=c instanceof MainActivity&&((MainActivity)c).hidden;
  for(int i=0;i<values.length;i++){lo=Math.min(lo,values[i]);hi=Math.max(hi,values[i]);pointDescriptions[i]=labels!=null&&i<labels.length&&labels[i]!=null?labels[i]:"Punto "+(i+1)+" · "+(hidden?"••••••":BolsilloWidget.money(values[i]));}min=lo;max=hi;low=hidden?"••••••":BolsilloWidget.money(min);high=hidden?"••••••":BolsilloWidget.money(max);
  setContentDescription(labels==null?"Evolución del saldo registrado. Mínimo "+low+". Máximo "+high:"Gráfico. Selecciona un punto para consultar fecha y monto. "+String.join(". ",pointDescriptions));setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);if(labels!=null){setClickable(true);setFocusable(true);}
 }
 @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){
  super.onSizeChanged(w,h,oldw,oldh);float dp=getResources().getDisplayMetrics().density,sp=getResources().getDisplayMetrics().scaledDensity;left=16*dp;right=Math.max(left,w-16*dp);top=labels!=null?43*dp:25*dp;bottom=Math.max(top+1,h-23*dp);if(bottom>h-3*dp){top=Math.max(2*dp,h*.38f);bottom=Math.max(top+1,h-4*dp);}tone=night?color:Glass.mix(color,Glass.ink(getContext()),.26f);
  line.reset();fill.reset();double span=max>=0&&min<0?(double)max-(double)min:(double)(max-min);for(int i=0;i<values.length;i++){xs[i]=values.length==1?(left+right)/2:left+(right-left)*i/Math.max(1,values.length-1);double delta=values[i]>=0&&min<0?(double)values[i]-(double)min:(double)(values[i]-min);ys[i]=max==min?(top+bottom)/2:bottom-(bottom-top)*(float)(delta/span);if(i==0)line.moveTo(xs[i],ys[i]);else line.lineTo(xs[i],ys[i]);}if(values.length>0){fill.set(line);fill.lineTo(xs[values.length-1],bottom);fill.lineTo(xs[0],bottom);fill.close();}
  fillMaterial=new LinearGradient(0,top,0,bottom,new int[]{Glass.alpha(tone,night?73:57),Glass.alpha(Glass.primary(getContext()),12),Glass.alpha(tone,0)},new float[]{0,.72f,1},Shader.TileMode.CLAMP);lineMaterial=new LinearGradient(left,top,right,bottom,new int[]{Glass.mix(tone,Glass.primary(getContext()),.15f),tone},null,Shader.TileMode.CLAMP);tooltipMaterial=new LinearGradient(0,0,w,38*dp,new int[]{Glass.mix(Glass.panel(getContext()),Glass.secondary(getContext()),night?.20f:.12f),Glass.panel(getContext())},null,Shader.TileMode.CLAMP);
  p.setTypeface(medium);labelSize=Math.min(10*sp,12*dp);p.setTextSize(labelSize);while(Math.max(p.measureText(low),p.measureText(high))>(right-left)*.62f&&labelSize>8*sp){labelSize-=.5f;p.setTextSize(labelSize);}tooltipSize=Math.min(12*sp,14*dp);p.setTextSize(tooltipSize);for(String text:pointDescriptions)while(p.measureText(text)>Math.max(1,w-54*dp)&&tooltipSize>8*sp){tooltipSize-=.5f;p.setTextSize(tooltipSize);}android.text.TextPaint textPaint=new android.text.TextPaint(p);for(int i=0;i<displayLabels.length;i++)displayLabels[i]=android.text.TextUtils.ellipsize(pointDescriptions[i],textPaint,Math.max(1,w-54*dp),android.text.TextUtils.TruncateAt.END).toString();tooltip.set(left,3*dp,right,32*dp);
 }
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();if(values.length>0&&ValueAnimator.areAnimatorsEnabled()){reveal=0;animation=ValueAnimator.ofFloat(0,1);animation.setDuration(600);animation.setInterpolator(new android.view.animation.DecelerateInterpolator(1.5f));animation.addUpdateListener(v->{reveal=(float)v.getAnimatedValue();invalidate();});animation.start();}else reveal=1;}
 @Override protected void onDetachedFromWindow(){if(animation!=null){animation.cancel();animation.removeAllUpdateListeners();animation=null;}reveal=1;super.onDetachedFromWindow();}
 int nearest(float x){int chosen=0;for(int i=1;i<xs.length;i++)if(Math.abs(x-xs[i])<Math.abs(x-xs[chosen]))chosen=i;return chosen;}
 void select(int point,boolean announce){if(values.length==0)return;selected=Math.max(0,Math.min(values.length-1,point));invalidate();if(Build.VERSION.SDK_INT>=30)setStateDescription(pointDescriptions[selected]);if(announce)announceForAccessibility(pointDescriptions[selected]);}
 @Override public boolean onTouchEvent(MotionEvent event){
  if(labels==null||values.length==0)return super.onTouchEvent(event);int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){downX=event.getX();downY=event.getY();dragged=false;return true;}if(action==MotionEvent.ACTION_MOVE){float dx=event.getX()-downX,dy=event.getY()-downY;int slop=ViewConfiguration.get(getContext()).getScaledTouchSlop();if(Math.abs(dx)>slop&&Math.abs(dx)>Math.abs(dy)*1.2f){dragged=true;if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(true);select(nearest(event.getX()),false);}return true;}if(action==MotionEvent.ACTION_UP){if(dragged||Math.hypot(event.getX()-downX,event.getY()-downY)<ViewConfiguration.get(getContext()).getScaledTouchSlop()){select(nearest(event.getX()),true);performClick();}if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(false);return true;}if(action==MotionEvent.ACTION_CANCEL){if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;
 }
 @Override public boolean performClick(){super.performClick();return true;}
 @Override public boolean onKeyDown(int key,KeyEvent event){if(labels!=null&&(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT)){select(selected<0?0:selected+(key==KeyEvent.KEYCODE_DPAD_RIGHT?1:-1),true);return true;}return super.onKeyDown(key,event);}
 @Override public void onInitializeAccessibilityNodeInfo(AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);if(labels!=null&&values.length>0){info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_FORWARD);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_BACKWARD);}}
 @Override public boolean performAccessibilityAction(int action,Bundle args){if(labels!=null&&(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD||action==AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD)){select(selected<0?0:selected+(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD?1:-1),true);return true;}return super.performAccessibilityAction(action,args);}
 @Override protected void onDraw(Canvas canvas){
  super.onDraw(canvas);if(values.length==0||right<=left)return;float dp=getResources().getDisplayMetrics().density;p.setShader(null);p.setPathEffect(null);p.setAlpha(255);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp*.7f);p.setColor(night?0x1cdfe7ff:0x24606e8e);for(int i=0;i<=3;i++){float y=top+(bottom-top)*i/3;canvas.drawLine(left,y,right,y,p);}
  p.setStyle(Paint.Style.FILL);p.setTypeface(medium);p.setTextAlign(Paint.Align.LEFT);p.setTextSize(labelSize);p.setColor(Glass.subtle(getContext()));if(selected<0||labels==null)canvas.drawText(high,left,top-7*dp,p);canvas.drawText(low,left,bottom+16*dp,p);
  canvas.save();canvas.clipRect(left-4*dp,top-5*dp,left+(right-left)*reveal+4*dp,bottom+5*dp);p.setShader(fillMaterial);canvas.drawPath(fill,p);p.setShader(null);p.setColor(Glass.alpha(tone,night?22:15));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(7*dp);p.setStrokeJoin(Paint.Join.ROUND);p.setStrokeCap(Paint.Cap.ROUND);canvas.drawPath(line,p);p.setShader(lineMaterial);p.setAlpha(255);p.setStrokeWidth(2.35f*dp);canvas.drawPath(line,p);p.setShader(null);p.setStyle(Paint.Style.FILL);p.setColor(tone);for(int i=0;i<values.length;i++)if(xs[i]<=left+(right-left)*reveal+.1f){canvas.drawCircle(xs[i],ys[i],(values.length>20?2:2.7f)*dp,p);p.setColor(night?0xffeef9ff:Color.WHITE);canvas.drawCircle(xs[i],ys[i],(values.length>20?.7f:1)*dp,p);p.setColor(tone);}canvas.restore();
  if(selected>=0&&selected<values.length){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp);p.setPathEffect(guide);p.setColor(Glass.alpha(tone,110));canvas.drawLine(xs[selected],top,xs[selected],bottom,p);p.setPathEffect(null);p.setStyle(Paint.Style.FILL);p.setColor(Glass.alpha(tone,45));canvas.drawCircle(xs[selected],ys[selected],8*dp,p);p.setColor(tone);canvas.drawCircle(xs[selected],ys[selected],4.5f*dp,p);p.setColor(night?Color.WHITE:Glass.panel(getContext()));canvas.drawCircle(xs[selected],ys[selected],2*dp,p);
   p.setShader(tooltipMaterial);canvas.drawRoundRect(tooltip,11*dp,11*dp,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp*.7f);p.setColor(night?0x55ffffff:0x99ffffff);canvas.drawRoundRect(tooltip,11*dp,11*dp,p);p.setStyle(Paint.Style.FILL);p.setColor(tone);canvas.drawCircle(left+12*dp,tooltip.centerY(),3*dp,p);p.setColor(Glass.ink(getContext()));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(tooltipSize);p.setTypeface(medium);float baseline=tooltip.centerY()-(p.ascent()+p.descent())/2;canvas.drawText(displayLabels[selected],(left+right)/2+5*dp,baseline,p);
  }else if(labels!=null){p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.RIGHT);p.setTextSize(labelSize);p.setColor(Glass.subtle(getContext()));canvas.drawText("TOCA UN PUNTO",right,20*dp,p);}
 }
}
